const timeLabel=date=>date.slice(11,19);
function investigationCentre(cell){const params=new URLSearchParams(location.search),ra=Number(params.get('sourceRa')),dec=Number(params.get('sourceDec'));return params.has('sourceRa')&&params.has('sourceDec')&&Number.isFinite(ra)&&ra>=0&&ra<360&&Number.isFinite(dec)&&Math.abs(dec)<=90&&cellAt(ra,dec)===cell.id?{ra,dec}:center(cell.id);}
