  q('#cell-times').innerHTML=sameDay.length>1?sameDay.map(o=>`<button data-exposure="${escape(o.path)}" class="${o.path===panel.path?'selected':''}" aria-pressed="${o.path===panel.path}">${timeLabel(o.date)} <span>${o.wavelength.toFixed(3)} µm</span></button>`).join(''):'';
  q('#cell-date').textContent=dualView?(active==='left'?'Left':'Right')+' viewer':'Observation';q('#cell-count').textContent=list.length+' exposures · ≥80% coverage';q('#cell-prev').disabled=i<=0;q('#cell-next').disabled=!list.length||i===list.length-1;q('#cell-play').disabled=list.length<2||checking;
  const skipped=items.filter(o=>o.lowCoverage).length;q('#cell-index-progress').textContent=[checking?`${items.filter(o=>o.checked).length} / ${items.length} checked`:failures?`${failures} unavailable`:'',skipped?`${skipped} below 80% coverage`:''].filter(Boolean).join(' · ');q('#cell-index-retry').hidden=checking||!failures;q('#cell-preload-retry').disabled=checking;info();
